1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { UsuariosService } from '../usuarios/usuarios.service';
5	import { PagBankClient } from '../pagamentos/pagbank.client';
6	import { CriarPlanoDto } from './dto/criar-plano.dto';
7	import { AtualizarPlanoDto } from './dto/atualizar-plano.dto';
8	
9	const STATUS_PAGOS = ['PAID', 'COMPLETED', 'AVAILABLE'];
10	
11	// Titular de uma assinatura: loja do SaaS multi-tenant OU instalação local licenciada.
12	// Exatamente um dos dois — nunca os dois, nunca nenhum (mesma regra do CHECK no banco).
13	export type Titular = { restaurantId: number } | { instalacaoId: number };
14	
15	const MESES_POR_PERIODICIDADE: Record<string, number> = {
16	  mensal: 1,
17	  trimestral: 3,
18	  anual: 12,
19	};
20	
21	const somarMeses = (data: Date, meses: number) => {
22	  const d = new Date(data);
23	  d.setMonth(d.getMonth() + meses);
24	  return d;
25	};
26	
27	const somarDias = (data: Date, dias: number) => {
28	  const d = new Date(data);
29	  d.setDate(d.getDate() + dias);
30	  return d;
31	};
32	
33	@Injectable()
34	export class PlanosService {
35	  constructor(
36	    private supabase: SupabaseService,
37	    private config: ConfigService,
38	    private usuarios: UsuariosService,
39	  ) {}
40	
41	  // Eleva o dono da loja assim que um pagamento (ou trial sem cobrança) é
42	  // confirmado — não espera o resto da wizard de cadastro (endereço, horários
43	  // etc.) ser preenchido. Sem isso, um dono que pagou mas fechou o navegador
44	  // antes do último passo da wizard nunca ganhava o painel. Idempotente e
45	  // seguro de chamar em toda fatura paga, inclusive renovação.
46	  private async elevarDonoSeNecessario(restaurantId: number | null | undefined) {
47	    if (!restaurantId) return;
48	    const { data: restaurante } = await this.supabase.client
49	      .from('restaurants')
50	      .select('user_id')
51	      .eq('id', restaurantId)
52	      .maybeSingle();
53	    if (restaurante?.user_id) {
54	      await this.usuarios.sincronizarVinculoDono(restaurantId, restaurante.user_id);
55	    }
56	  }
57	
58	  // ── CRUD de planos ──────────────────────────────────────────────
59	
60	  async listarPlanos() {
61	    const { data, error } = await this.supabase.client
62	      .from('planos')
63	      .select('*')
64	      .order('valor', { ascending: true });
65	    if (error) throw error;
66	    return { planos: data ?? [] };
67	  }
68	
69	  // Planos que o dono pode escolher na tela de upgrade — só os ativos do tipo certo
70	  async listarPlanosAtivos(tipo: 'saas' | 'local' = 'saas') {
71	    const { data, error } = await this.supabase.client
72	      .from('planos')
73	      .select('*')
74	      .eq('ativo', true)
75	      .eq('tipo', tipo)
76	      .order('valor', { ascending: true });
77	    if (error) throw error;
78	    return { planos: data ?? [] };
79	  }
80	
81	  async buscarPlano(id: number) {
82	    const { data, error } = await this.supabase.client
83	      .from('planos')
84	      .select('*')
85	      .eq('id', id)
86	      .maybeSingle();
87	    if (error) throw error;
88	    if (!data) throw new NotFoundException('Plano não encontrado');
89	    return data;
90	  }
91	
92	  private async garantirNomePlanoUnico(nome: string, ignorarId?: number) {
93	    let query = this.supabase.client.from('planos').select('id').ilike('nome', nome.trim());
94	    if (ignorarId) query = query.neq('id', ignorarId);
95	    const { data, error } = await query;
96	    if (error) throw error;
97	    if (data && data.length > 0) {
98	      throw new ConflictException(`Já existe um plano chamado "${nome.trim()}"`);
99	    }
100	  }
101	
102	  async criarPlano(body: CriarPlanoDto) {
103	    await this.garantirNomePlanoUnico(body.nome);
104	
105	    const { data, error } = await this.supabase.client
106	      .from('planos')
107	      .insert({
108	        nome: body.nome,
109	        valor: body.valor,
110	        periodicidade: body.periodicidade,
111	        tipo: body.tipo ?? 'saas',
112	        limite_produtos: body.limite_produtos ?? null,
113	        piso_faturamento: body.piso_faturamento ?? null,
114	        trial_dias: body.trial_dias ?? 0,
115	        ativo: body.ativo ?? true,
116	        inclui_delivery: body.inclui_delivery ?? true,
117	        inclui_salao: body.inclui_salao ?? false,
118	      })
119	      .select()
120	      .single();
121	    if (error) throw error;
122	    return data;
123	  }
124	
125	  async atualizarPlano(id: number, body: AtualizarPlanoDto) {
126	    if (body.nome !== undefined) await this.garantirNomePlanoUnico(body.nome, id);
127	
128	    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
129	    if (body.nome !== undefined) campos.nome = body.nome;
130	    if (body.valor !== undefined) campos.valor = body.valor;
131	    if (body.periodicidade !== undefined) campos.periodicidade = body.periodicidade;
132	    if (body.tipo !== undefined) campos.tipo = body.tipo;
133	    if (body.limite_produtos !== undefined) campos.limite_produtos = body.limite_produtos;
134	    if (body.piso_faturamento !== undefined) campos.piso_faturamento = body.piso_faturamento;
135	    if (body.trial_dias !== undefined) campos.trial_dias = body.trial_dias;
136	    if (body.ativo !== undefined) campos.ativo = body.ativo;
137	    if (body.inclui_delivery !== undefined) campos.inclui_delivery = body.inclui_delivery;
138	    if (body.inclui_salao !== undefined) campos.inclui_salao = body.inclui_salao;
139	
140	    const { data, error } = await this.supabase.client
141	      .from('planos')
142	      .update(campos)
143	      .eq('id', id)
144	      .select()
145	      .single();
146	    if (error) throw error;
147	    if (!data) throw new NotFoundException('Plano não encontrado');
148	    return data;
149	  }
150	
151	  async removerPlano(id: number) {
152	    const { count, error: countErro } = await this.supabase.client
153	      .from('assinaturas')
154	      .select('id', { count: 'exact', head: true })
155	      .eq('plano_id', id);
156	    if (countErro) throw countErro;
157	    if ((count ?? 0) > 0) {
158	      throw new ConflictException(
159	        'Este plano tem lojas vinculadas — desative com "ativo: false" em vez de remover',
160	      );
161	    }
162	
163	    const { error } = await this.supabase.client.from('planos').delete().eq('id', id);
164	    if (error) throw error;
165	    return { ok: true };
166	  }
167	
168	  // ── Assinaturas (loja <-> plano) ────────────────────────────────
169	
170	  async listarAssinaturas() {
171	    const { data, error } = await this.supabase.client
172	      .from('assinaturas')
173	      .select('*, restaurants(name), planos(nome, valor, periodicidade)')
174	      .order('created_at', { ascending: false });
175	    if (error) throw error;
176	    return { assinaturas: data ?? [] };
177	  }
178	
179	  private async buscarAssinaturaRaw(titular: Titular) {
180	    let q = this.supabase.client.from('assinaturas').select('*, planos(*)');
181	    q = 'restaurantId' in titular ? q.eq('restaurant_id', titular.restaurantId) : q.eq('instalacao_id', titular.instalacaoId);
182	    const { data, error } = await q.maybeSingle();
183	    if (error) throw error;
184	    return data;
185	  }
186	
187	  async buscarAssinaturaPorRestaurante(restaurantId: number) {
188	    const assinatura = await this.buscarAssinaturaRaw({ restaurantId });
189	    if (!assinatura) throw new NotFoundException('Loja não tem assinatura');
190	
191	    const { data: faturas, error } = await this.supabase.client
192	      .from('plano_faturas')
193	      .select('*')
194	      .eq('restaurant_id', restaurantId)
195	      .order('periodo_inicio', { ascending: false });
196	    if (error) throw error;
197	
198	    return { assinatura, faturas: faturas ?? [] };
199	  }
200	
201	  async buscarAssinaturaPorInstalacao(instalacaoId: number) {
202	    const assinatura = await this.buscarAssinaturaRaw({ instalacaoId });
203	    if (!assinatura) throw new NotFoundException('Instalação não tem assinatura');
204	
205	    const { data: faturas, error } = await this.supabase.client
206	      .from('plano_faturas')
207	      .select('*')
208	      .eq('instalacao_id', instalacaoId)
209	      .order('periodo_inicio', { ascending: false });
210	    if (error) throw error;
211	
212	    return { assinatura, faturas: faturas ?? [] };
213	  }
214	
215	  async atribuirAssinatura(titular: Titular, planoId: number) {
216	    const plano = await this.buscarPlano(planoId);
217	
218	    if ('restaurantId' in titular) {
219	      const { data: restaurante, error: restErro } = await this.supabase.client
220	        .from('restaurants').select('id').eq('id', titular.restaurantId).maybeSingle();
221	      if (restErro) throw restErro;
222	      if (!restaurante) throw new NotFoundException('Loja não encontrada');
223	
224	      // Módulos liberados na loja passam a refletir o que o plano inclui
225	      const { error: moduloErro } = await this.supabase.client
226	        .from('restaurants')
227	        .update({
228	          modulo_delivery: plano.inclui_delivery,
229	          modulo_salao: plano.inclui_salao,
230	          updated_at: new Date().toISOString(),
231	        })
232	        .eq('id', titular.restaurantId);
233	      if (moduloErro) throw moduloErro;
234	    } else {
235	      const { data: instalacao, error: instErro } = await this.supabase.client
236	        .from('instalacoes_locais').select('id').eq('id', titular.instalacaoId).maybeSingle();
237	      if (instErro) throw instErro;
238	      if (!instalacao) throw new NotFoundException('Instalação não encontrada');
239	    }
240	
241	    const existente = await this.buscarAssinaturaRaw(titular);
242	    const agora = new Date();
243	    const temTrial = (plano.trial_dias ?? 0) > 0;
244	    const trialFim = temTrial ? somarDias(agora, plano.trial_dias) : null;
245	
246	    if (existente) {
247	      // Troca de plano reinicia o ciclo de cobrança: recalcula trial/status a
248	      // partir do plano novo (senão um plano com trial_dias=0 continuaria preso
249	      // no status "trial" herdado do plano anterior).
250	      const { data, error } = await this.supabase.client
251	        .from('assinaturas')
252	        .update({
253	          plano_id: planoId,
254	          status: temTrial ? 'trial' : 'ativa',
255	          trial_fim: trialFim?.toISOString() ?? null,
256	          ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
257	          updated_at: agora.toISOString(),
258	        })
259	        .eq('id', existente.id)
260	        .select()
261	        .single();
262	      if (error) throw error;
263	      return data;
264	    }
265	
266	    const novaAssinatura: Record<string, any> = {
267	      plano_id: planoId,
268	      status: temTrial ? 'trial' : 'ativa',
269	      data_inicio: agora.toISOString(),
270	      trial_fim: trialFim?.toISOString() ?? null,
271	      ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
272	    };
273	    if ('restaurantId' in titular) novaAssinatura.restaurant_id = titular.restaurantId;
274	    else novaAssinatura.instalacao_id = titular.instalacaoId;
275	
276	    const { data, error } = await this.supabase.client
277	      .from('assinaturas')
278	      .insert(novaAssinatura)
279	      .select()
280	      .single();
281	    if (error) throw error;
282	    return data;
283	  }
284	
285	  async cancelarAssinatura(titular: Titular) {
286	    const existente = await this.buscarAssinaturaRaw(titular);
287	    if (!existente) throw new NotFoundException('Assinatura não encontrada');
288	
289	    const { data, error } = await this.supabase.client
290	      .from('assinaturas')
291	      .update({ status: 'cancelada', data_cancelamento: new Date().toISOString(), updated_at: new Date().toISOString() })
292	      .eq('id', existente.id)
293	      .select()
294	      .single();
295	    if (error) throw error;
296	    return data;
297	  }
298	
299	  // ── Limite de produtos ──────────────────────────────────────────
300	
301	  async verificarLimiteProdutos(restaurantId: number) {
302	    const assinatura = await this.buscarAssinaturaRaw({ restaurantId });
303	    if (!assinatura || assinatura.status === 'cancelada') return; // loja sem plano = sem limite
304	    const limite = assinatura.planos?.limite_produtos;
305	    if (limite == null) return; // ilimitado
306	
307	    const { count, error } = await this.supabase.client
308	      .from('products')
309	      .select('id', { count: 'exact', head: true })
310	      .eq('restaurant_id', restaurantId)
311	      .eq('is_active', true);
312	    if (error) throw error;
313	
314	    if ((count ?? 0) >= limite) {
315	      throw new ForbiddenException(
316	        `Limite de ${limite} produtos do plano "${assinatura.planos.nome}" atingido. Faça upgrade de plano para cadastrar mais produtos.`,
317	      );
318	    }
319	  }
320	
321	  // ── Faturamento / geração lazy de fatura ────────────────────────
322	
323	  private async diasTolerancia() {
324	    const { data } = await this.supabase.client
325	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
326	    const cfg = (data?.config ?? {}) as Record<string, any>;
327	    return cfg.plano_dias_tolerancia ?? 3;
328	  }
329	
330	  // Marca pendente->vencida, gera faturas de todo período fechado ainda não
331	  // faturado, e devolve o status atual de bloqueio da loja.
332	  // forcar=true também gera fatura do período atual mesmo que ainda não tenha
333	  // fechado (usado pelo botão "Renovar agora"/"Gerar fatura" sob demanda).
334	  async sincronizarPeriodo(titular: Titular, forcar = false) {
335	    const assinatura = await this.buscarAssinaturaRaw(titular);
336	    if (!assinatura || assinatura.status === 'cancelada') {
337	      return { bloqueado: false, dias_atraso: 0, fatura_pendente_id: null, plano_nome: null, proxima_cobranca: null };
338	    }
339	
340	    const agora = new Date();
341	    const plano = assinatura.planos;
342	    const meses = MESES_POR_PERIODICIDADE[plano.periodicidade] ?? 1;
343	
344	    // Marca vencidas
345	    await this.supabase.client
346	      .from('plano_faturas')
347	      .update({ status: 'vencida', atualizado_em: agora.toISOString() })
348	      .eq('assinatura_id', assinatura.id)
349	      .eq('status', 'pendente')
350	      .lt('vencimento', agora.toISOString());
351	
352	    // Gera períodos fechados pendentes de fatura (+ o período atual se forcar=true)
353	    let inicioPeriodo = assinatura.ultimo_periodo_faturado_fim
354	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
355	      : new Date(assinatura.data_inicio);
356	    let ultimoFimFaturado = assinatura.ultimo_periodo_faturado_fim
357	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
358	      : null;
359	
360	    // Se já existe fatura pendente/vencida/isenta de QUALQUER período, "Renovar
361	    // agora" não pode gerar outra. Isenta entra aqui também — senão clicar de
362	    // novo (a fatura isenta não bloqueia "pendente/vencida") empurra a cobrança
363	    // pro período seguinte a cada clique, gerando várias faturas de R$0 em
364	    // sequência.
365	    let temPendenteAberta = false;
366	    if (forcar) {
367	      const { data: pendenteExistente, error: pendErroCheck } = await this.supabase.client
368	        .from('plano_faturas')
369	        .select('id')
370	        .eq('assinatura_id', assinatura.id)
371	        .in('status', ['pendente', 'vencida', 'isenta'])
372	        .is('plano_id_troca', null)
373	        .limit(1)
374	        .maybeSingle();
375	      if (pendErroCheck) throw pendErroCheck;
376	      temPendenteAberta = !!pendenteExistente;
377	    }
378	
379	    // eslint-disable-next-line no-constant-condition
380	    while (true) {
381	      const fimPeriodo = somarMeses(inicioPeriodo, meses);
382	      const periodoFechado = fimPeriodo < agora;
383	      if (!periodoFechado && !forcar) break;
384	
385	      if (!periodoFechado) {
386	        if (temPendenteAberta) break;
387	
388	        // Período em aberto forçado: se já existe fatura pra esse período (de um
389	        // "Renovar agora" anterior), não gera outra nem avança o ciclo de novo —
390	        // senão cada clique empurraria a cobrança um mês pra frente.
391	        const { data: jaExiste, error: existeErro } = await this.supabase.client
392	          .from('plano_faturas')
393	          .select('id')
394	          .eq('assinatura_id', assinatura.id)
395	          .eq('periodo_inicio', inicioPeriodo.toISOString())
396	          .maybeSingle();
397	        if (existeErro) throw existeErro;
398	        if (jaExiste) break;
399	      }
400	
401	      // Isenção por piso de faturamento só existe pro SaaS — instalação local
402	      // não tem pedidos na tabela `orders` central (banco próprio, separado),
403	      // então sempre cobra o valor cheio do plano.
404	      let isento = false;
405	      let valorFatura = plano.valor;
406	      if ('restaurantId' in titular) {
407	        const { data: faturamentoRows, error: fatErro } = await this.supabase.client
408	          .from('orders')
409	          .select('total')
410	          .eq('restaurant_id', titular.restaurantId)
411	          .eq('status', 'delivered')
412	          .gte('created_at', inicioPeriodo.toISOString())
413	          .lt('created_at', fimPeriodo.toISOString());
414	        if (fatErro) throw fatErro;
415	
416	        const faturamento = (faturamentoRows ?? []).reduce((acc, o: any) => acc + (o.total ?? 0), 0);
417	        isento = plano.piso_faturamento != null && faturamento < plano.piso_faturamento;
418	        valorFatura = isento ? 0 : plano.valor;
419	      }
420	
421	      const vencimento = somarDias(fimPeriodo, 5);
422	
423	      const novaFatura: Record<string, any> = {
424	        assinatura_id: assinatura.id,
425	        periodo_inicio: inicioPeriodo.toISOString(),
426	        periodo_fim: fimPeriodo.toISOString(),
427	        valor: valorFatura,
428	        status: isento ? 'isenta' : 'pendente',
429	        vencimento: vencimento.toISOString(),
430	      };
431	      if ('restaurantId' in titular) novaFatura.restaurant_id = titular.restaurantId;
432	      else novaFatura.instalacao_id = titular.instalacaoId;
433	
434	      const { error: insErro } = await this.supabase.client
435	        .from('plano_faturas')
436	        .insert(novaFatura);
437	      // Ignora conflito de unicidade (fatura já gerada em corrida concorrente)
438	      if (insErro && !String(insErro.message).includes('duplicate')) throw insErro;
439	
440	      ultimoFimFaturado = fimPeriodo;
441	      inicioPeriodo = fimPeriodo;
442	
443	      if (!periodoFechado) break; // gerou o período em aberto sob demanda — não continua pro futuro
444	    }
445	
446	    if (ultimoFimFaturado && ultimoFimFaturado.getTime() !== new Date(assinatura.ultimo_periodo_faturado_fim ?? 0).getTime()) {
447	      await this.supabase.client
448	        .from('assinaturas')
449	        .update({ ultimo_periodo_faturado_fim: ultimoFimFaturado.toISOString(), updated_at: agora.toISOString() })
450	        .eq('id', assinatura.id);
451	    }
452	
453	    // Recalcula bloqueio com base no estado atual das faturas
454	    const tolerancia = await this.diasTolerancia();
455	    const { data: pendentes, error: pendErro } = await this.supabase.client
456	      .from('plano_faturas')
457	      .select('id, vencimento, status')
458	      .eq('assinatura_id', assinatura.id)
459	      .in('status', ['pendente', 'vencida'])
460	      .is('plano_id_troca', null)
461	      .order('vencimento', { ascending: true });
462	    if (pendErro) throw pendErro;
463	
464	    let bloqueado = false;
465	    let diasAtraso = 0;
466	    let faturaPendenteId: number | null = null;
467	    if ((pendentes ?? []).length > 0) {
468	      faturaPendenteId = pendentes[0].id;
469	      const vencimento = new Date(pendentes[0].vencimento);
470	      diasAtraso = Math.max(0, Math.floor((agora.getTime() - vencimento.getTime()) / 86400000));
471	      bloqueado = diasAtraso > tolerancia;
472	    }
473	
474	    const proximaCobranca = somarMeses(ultimoFimFaturado ?? inicioPeriodo, meses);
475	
476	    return {
477	      bloqueado,
478	      dias_atraso: diasAtraso,
479	      fatura_pendente_id: faturaPendenteId,
480	      plano_nome: plano.nome,
481	      proxima_cobranca: proximaCobranca.toISOString(),
482	    };
483	  }
484	
485	  async detalhePlanoRestaurante(restaurantId: number) {
486	    const status = await this.sincronizarPeriodo({ restaurantId });
487	    const { assinatura, faturas } = await this.buscarAssinaturaPorRestaurante(restaurantId);
488	
489	    const { count: produtosAtivos, error } = await this.supabase.client
490	      .from('products')
491	      .select('id', { count: 'exact', head: true })
492	      .eq('restaurant_id', restaurantId)
493	      .eq('is_active', true);
494	    if (error) throw error;
495	
496	    return {
497	      ...status,
498	      assinatura,
499	      faturas,
500	      produtos_ativos: produtosAtivos ?? 0,
501	      limite_produtos: assinatura.planos?.limite_produtos ?? null,
502	    };
503	  }
504	
505	  async gerarFaturaManual(restaurantId: number) {
506	    await this.sincronizarPeriodo({ restaurantId }, true);
507	    return this.buscarAssinaturaPorRestaurante(restaurantId);
508	  }
509	
510	  // Dono renovando/antecipando a cobrança da própria loja pelo painel do plano
511	  async renovarAgora(restaurantId: number) {
512	    return this.sincronizarPeriodo({ restaurantId }, true);
513	  }
514	
515	  // Dono pedindo upgrade/downgrade — não troca na hora, gera uma fatura do
516	  // valor cheio do plano novo. A troca só é aplicada quando essa fatura é
517	  // confirmada paga (ver aplicarTrocaSeNecessario).
518	  async iniciarTrocaPlano(restaurantId: number, planoId: number) {
519	    const assinatura = await this.buscarAssinaturaRaw({ restaurantId });
520	    if (!assinatura) throw new NotFoundException('Loja não tem assinatura');
521	
522	    const plano = await this.buscarPlano(planoId);
523	    if (plano.tipo !== 'saas') throw new BadRequestException('Plano inválido');
524	    if (plano.id === assinatura.plano_id) throw new BadRequestException('Já está nesse plano');
525	
526	    const agora = new Date();
527	    const { data, error } = await this.supabase.client
528	      .from('plano_faturas')
529	      .insert({
530	        assinatura_id: assinatura.id,
531	        restaurant_id: restaurantId,
532	        plano_id_troca: planoId,
533	        periodo_inicio: agora.toISOString(),
534	        periodo_fim: agora.toISOString(),
535	        valor: plano.valor,
536	        status: 'pendente',
537	        vencimento: agora.toISOString(),
538	      })
539	      .select()
540	      .single();
541	    if (error) throw error;
542	    return data;
543	  }
544	
545	  // Chamado depois que uma fatura é confirmada paga (Pix webhook ou cartão na
546	  // hora) — se ela tinha plano_id_troca marcado, aplica a troca de plano agora.
547	  private async aplicarTrocaSeNecessario(fatura: any) {
548	    if (!fatura.plano_id_troca || !fatura.restaurant_id) return;
549	    await this.atribuirAssinatura({ restaurantId: fatura.restaurant_id }, fatura.plano_id_troca);
550	  }
551	
552	  async gerarFaturaManualInstalacao(instalacaoId: number) {
553	    await this.sincronizarPeriodo({ instalacaoId }, true);
554	    return this.buscarAssinaturaPorInstalacao(instalacaoId);
555	  }
556	
557	  // ── Faturas (visão admin) ───────────────────────────────────────
558	
559	  async listarFaturas(filtros: { restaurant_id?: number; status?: string; tipo?: 'saas' | 'local' }) {
560	    let q = this.supabase.client
561	      .from('plano_faturas')
562	      .select('*, restaurants(name), instalacoes_locais(nome_cliente, serial)')
563	      .order('vencimento', { ascending: false });
564	    if (filtros.restaurant_id) q = q.eq('restaurant_id', filtros.restaurant_id);
565	    if (filtros.status) q = q.eq('status', filtros.status);
566	    if (filtros.tipo === 'saas') q = q.not('restaurant_id', 'is', null);
567	    if (filtros.tipo === 'local') q = q.not('instalacao_id', 'is', null);
568	    const { data, error } = await q;
569	    if (error) throw error;
570	    return { faturas: data ?? [] };
571	  }
572	
573	  async buscarFatura(id: number) {
574	    const { data, error } = await this.supabase.client
575	      .from('plano_faturas').select('*').eq('id', id).maybeSingle();
576	    if (error) throw error;
577	    if (!data) throw new NotFoundException('Fatura não encontrada');
578	    return data;
579	  }
580	
581	  async buscarFaturaDoRestaurante(restaurantId: number, id: number) {
582	    const fatura = await this.buscarFatura(id);
583	    if (fatura.restaurant_id !== restaurantId) throw new NotFoundException('Fatura não encontrada');
584	    return fatura;
585	  }
586	
587	  async marcarFaturaPaga(id: number) {
588	    const { data, error } = await this.supabase.client
589	      .from('plano_faturas')
590	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
591	      .eq('id', id)
592	      .select()
593	      .single();
594	    if (error) throw error;
595	    if (!data) throw new NotFoundException('Fatura não encontrada');
596	
597	    await this.aplicarTrocaSeNecessario(data);
598	    await this.elevarDonoSeNecessario(data.restaurant_id);
599	
600	    return data;
601	  }
602	
603	  // ── Pagamento via PagBank (cobrança direta loja -> plataforma, sem split) ──
604	
605	  private async clientPlataforma() {
606	    const { data: platData } = await this.supabase.client
607	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
608	    const platCfg = (platData?.config ?? {}) as Record<string, any>;
609	
610	    const token = platCfg.pagbank_platform_token || this.config.get<string>('PAGBANK_PLATFORM_TOKEN') || '';
611	    if (!token) throw new BadRequestException('PagBank da plataforma não configurado — fale com o suporte');
612	    const sandbox = platCfg.pagbank_sandbox ?? (this.config.get('PAGBANK_SANDBOX') !== 'false');
613	
614	    const baseWebhook =
615	      platCfg.pagbank_webhook_url ||
616	      this.config.get<string>('PAGBANK_WEBHOOK_URL') ||
617	      'http://localhost:3002/pagamentos/webhook';
618	    const webhookUrl = baseWebhook.replace('/pagamentos/webhook', '/planos/webhook');
619	
620	    return { client: new PagBankClient(token, sandbox), webhookUrl };
621	  }
622	
623	  // Chave pública pro PagBank.js criptografar o cartão no navegador do dono
624	  async buscarChavePublicaCartao() {
625	    const { client } = await this.clientPlataforma();
626	    try {
627	      const resposta = await client.buscarChavePublica();
628	      return { public_key: resposta.public_key };
629	    } catch (e: any) {
630	      throw new BadRequestException(e?.message ?? 'Falha ao obter chave pública do PagBank');
631	    }
632	  }
633	
634	  async pagarFatura(
635	    restaurantId: number,
636	    faturaId: number,
637	    body: { nome: string; email: string; cpf_cnpj: string; metodo?: 'pix' | 'credit_card' | 'debit_card'; card_encrypted?: string; parcelas?: number },
638	  ) {
639	    const fatura = await this.buscarFaturaDoRestaurante(restaurantId, faturaId);
640	    if (fatura.status === 'paga') throw new BadRequestException('Fatura já está paga');
641	    if (fatura.status === 'isenta' || fatura.status === 'cancelada') {
642	      throw new BadRequestException('Esta fatura não pode ser paga');
643	    }
644	
645	    const metodo = body.metodo ?? 'pix';
646	    if (metodo === 'credit_card' || metodo === 'debit_card') {
647	      return this.pagarFaturaCartao(fatura, body, metodo);
648	    }
649	
650	    // Reaproveita o QR já gerado pra essa fatura em vez de abrir ordem nova a cada clique
651	    if (fatura.pix_code && fatura.pagbank_order_id) {
652	      return { pix_code: fatura.pix_code, pix_qr_url: fatura.pix_qr_url, fatura_id: fatura.id };
653	    }
654	
655	    const { client, webhookUrl } = await this.clientPlataforma();
656	
657	    const valorCentavos = Math.round(fatura.valor * 100);
658	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
659	
660	    let resposta: any;
661	    try {
662	      resposta = await client.criarOrdemPix({
663	        reference_id: refId,
664	        valor_centavos: valorCentavos,
665	        customer: {
666	          name: body.nome,
667	          email: body.email,
668	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
669	        },
670	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
671	        webhook_url: webhookUrl,
672	      });
673	    } catch (e: any) {
674	      throw new BadRequestException(e?.message ?? 'Falha ao gerar cobrança no PagBank');
675	    }
676	
677	    const qrCode = resposta?.qr_codes?.[0];
678	    const pixCode = qrCode?.text ?? null;
679	    const pixQrUrl = qrCode?.links?.find((l: any) => l.media === 'image/png')?.href ?? null;
680	
681	    const { error } = await this.supabase.client
682	      .from('plano_faturas')
683	      .update({
684	        pagbank_order_id: resposta.id,
685	        reference_id: refId,
686	        pix_code: pixCode,
687	        pix_qr_url: pixQrUrl,
688	        atualizado_em: new Date().toISOString(),
689	      })
690	      .eq('id', fatura.id);
691	    if (error) throw error;
692	
693	    return { pix_code: pixCode, pix_qr_url: pixQrUrl, fatura_id: fatura.id };
694	  }
695	
696	  // Cartão confirma na hora (sem espera de webhook) — diferente do Pix
697	  private async pagarFaturaCartao(
698	    fatura: any,
699	    body: { nome: string; email: string; cpf_cnpj: string; card_encrypted?: string; parcelas?: number },
700	    metodo: 'credit_card' | 'debit_card',
701	  ) {
702	    if (!body.card_encrypted) throw new BadRequestException('Dados do cartão ausentes');
703	
704	    const { client, webhookUrl } = await this.clientPlataforma();
705	    const valorCentavos = Math.round(fatura.valor * 100);
706	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
707	
708	    let resposta: any;
709	    try {
710	      resposta = await client.criarOrdemCartao({
711	        reference_id: refId,
712	        valor_centavos: valorCentavos,
713	        customer: {
714	          name: body.nome,
715	          email: body.email,
716	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
717	        },
718	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
719	        card_encrypted: body.card_encrypted,
720	        parcelas: metodo === 'credit_card' ? (body.parcelas ?? 1) : 1,
721	        tipo: metodo === 'credit_card' ? 'CREDIT_CARD' : 'DEBIT_CARD',
722	        webhook_url: webhookUrl,
723	      });
724	    } catch (e: any) {
725	      throw new BadRequestException(e?.message ?? 'Falha ao processar cartão no PagBank');
726	    }
727	
728	    const charge = resposta?.charges?.[0];
729	    const pago = STATUS_PAGOS.includes(charge?.status);
730	
731	    const { error } = await this.supabase.client
732	      .from('plano_faturas')
733	      .update({
734	        pagbank_order_id: resposta.id,
735	        reference_id: refId,
736	        status: pago ? 'paga' : fatura.status,
737	        pago_em: pago ? new Date().toISOString() : null,
738	        atualizado_em: new Date().toISOString(),
739	      })
740	      .eq('id', fatura.id);
741	    if (error) throw error;
742	
743	    if (!pago) {
744	      throw new BadRequestException(charge?.status === 'DECLINED' ? 'Cartão recusado' : 'Pagamento não aprovado, tente novamente');
745	    }
746	
747	    await this.aplicarTrocaSeNecessario(fatura);
748	    await this.elevarDonoSeNecessario(fatura.restaurant_id);
749	
750	    return { pago: true, fatura_id: fatura.id };
751	  }
752	
753	  async processarWebhook(evento: any) {
754	    const payload = evento?.data ?? evento;
755	    const pagbankOrderId: string = payload?.id ?? payload?.reference_id;
756	    if (!pagbankOrderId) return { ignorado: true };
757	
758	    const { data: fatura } = await this.supabase.client
759	      .from('plano_faturas')
760	      .select('id, status, restaurant_id, plano_id_troca')
761	      .eq('pagbank_order_id', pagbankOrderId)
762	      .maybeSingle();
763	
764	    if (!fatura) return { ignorado: true, motivo: 'fatura não encontrada' };
765	    if (fatura.status === 'paga') return { ignorado: true, motivo: 'já processado' };
766	
767	    // PagBank não assina notificações — nunca confiar no status vindo no corpo
768	    // do POST. Reconsulta a ordem direto na API do PagBank (mesma correção
769	    // aplicada em pagamentos.service.ts) antes de marcar a fatura como paga.
770	    const { client } = await this.clientPlataforma();
771	    const ordemReal = await client.buscarOrdem(pagbankOrderId);
772	    const detalhe = ordemReal?.charges?.[0] ?? ordemReal?.payments?.[0];
773	    if (!detalhe) return { ignorado: true };
774	
775	    const statusPagbank: string = detalhe?.status ?? '';
776	    if (!STATUS_PAGOS.includes(statusPagbank)) return { ignorado: true };
777	
778	    await this.supabase.client
779	      .from('plano_faturas')
780	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
781	      .eq('id', fatura.id);
782	
783	    await this.aplicarTrocaSeNecessario(fatura);
784	    await this.elevarDonoSeNecessario(fatura.restaurant_id);
785	
786	    return { processado: true, fatura_id: fatura.id };
787	  }
788	}
