  }

  @Post('jobs/:id/concluido')
  marcarProcessado(@Param('id', ParseIntPipe) id: number, @Body() body: { venda_id_gdoor?: string }, @Req() req: any) {
    return this.service.marcarProcessado(id, req.agenteRestaurantId, body.venda_id_gdoor ?? '');
  }

  @Post('jobs/:id/erro')
