1	import React, { useState, useEffect, useCallback } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import {
4	  getPlanos, criarPlano, atualizarPlano, removerPlano,
5	  getAssinaturas, atribuirAssinatura, cancelarAssinatura, gerarFaturaManual,
6	  getFaturas, marcarFaturaPaga,
7	} from '../../services/planosService';
8	import {
9	  getInstalacoes, criarInstalacao, atualizarInstalacao,
10	  atribuirPlanoInstalacao, gerarFaturaManualInstalacao,
11	} from '../../services/instalacoesService';
12	import { getEmpresas } from '../../services/adminService';
13	import Icon from '../../components/AppIcon';
14	import AdminHeader from '../../components/admin/AdminHeader';
15	
16	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
17	const fmtData = (v) => v ? new Date(v).toLocaleDateString('pt-BR') : '—';
18	
19	const PERIODICIDADES = [
20	  { value: 'mensal', label: 'Mensal' },
21	  { value: 'trimestral', label: 'Trimestral' },
22	  { value: 'anual', label: 'Anual' },
23	];
24	
25	const STATUS_LABEL = {
26	  trial: { label: 'Trial', cls: 'bg-blue-100 dark:bg-blue-950/40 text-blue-700 dark:text-blue-400' },
27	  ativa: { label: 'Ativa', cls: 'bg-green-100 dark:bg-green-950/40 text-green-700 dark:text-green-400' },
28	  cancelada: { label: 'Cancelada', cls: 'bg-gray-100 dark:bg-zinc-700 text-gray-500 dark:text-zinc-400' },
29	  pendente: { label: 'Pendente', cls: 'bg-amber-100 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400' },
30	  paga: { label: 'Paga', cls: 'bg-green-100 dark:bg-green-950/40 text-green-700 dark:text-green-400' },
31	  vencida: { label: 'Vencida', cls: 'bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400' },
32	  isenta: { label: 'Isenta', cls: 'bg-gray-100 dark:bg-zinc-700 text-gray-500 dark:text-zinc-400' },
33	};
34	
35	const Badge = ({ status }) => {
36	  const s = STATUS_LABEL[status] ?? { label: status, cls: 'bg-gray-100 dark:bg-zinc-700 text-gray-500 dark:text-zinc-400' };
37	  return <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${s.cls}`}>{s.label}</span>;
38	};
39	
40	/* ── Normaliza nome pra comparar sem acento/maiúscula ───────────── */
41	const normalizarNome = (s) =>
42	  (s ?? '').normalize('NFD').replace(/\p{Diacritic}/gu, '').trim().toLowerCase();
43	
44	const EMPTY = { nome: '', valor: '', periodicidade: 'mensal', tipo: 'saas', limite_produtos: '', piso_faturamento: '', trial_dias: '0', ativo: true, inclui_delivery: true, inclui_salao: false };
45	
46	const Modal = ({ plano, planosExistentes, onClose, onSave }) => {
47	  const [form, setForm] = useState(
48	    plano
49	      ? {
50	          nome: plano.nome,
51	          valor: String(plano.valor),
52	          periodicidade: plano.periodicidade,
53	          tipo: plano.tipo ?? 'saas',
54	          limite_produtos: plano.limite_produtos != null ? String(plano.limite_produtos) : '',
55	          piso_faturamento: plano.piso_faturamento != null ? String(plano.piso_faturamento) : '',
56	          trial_dias: String(plano.trial_dias ?? 0),
57	          ativo: plano.ativo,
58	          inclui_delivery: plano.inclui_delivery ?? true,
59	          inclui_salao: plano.inclui_salao ?? false,
60	        }
61	      : { ...EMPTY }
62	  );
63	  const isLocal = form.tipo === 'local';
64	  const [salvando, setSalvando] = useState(false);
65	  const [erro, setErro] = useState(null);
66	  const isEdicao = !!plano;
67	
68	  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
69	
70	  const handleSubmit = async (e) => {
71	    e.preventDefault();
72	    if (!form.nome.trim() || !form.valor) return;
73	
74	    const nomeNormalizado = normalizarNome(form.nome);
75	    const duplicado = (planosExistentes ?? []).find(
76	      (p) => p.id !== plano?.id && normalizarNome(p.nome) === nomeNormalizado
77	    );
78	    if (duplicado) {
79	      setErro(`Já existe um plano chamado "${duplicado.nome}"`);
80	      return;
81	    }
82	
83	    setSalvando(true);
84	    setErro(null);
85	    try {
86	      const body = {
87	        nome: form.nome.trim(),
88	        valor: parseFloat(form.valor),
89	        periodicidade: form.periodicidade,
90	        tipo: form.tipo,
91	        limite_produtos: form.limite_produtos.trim() ? parseInt(form.limite_produtos, 10) : null,
92	        piso_faturamento: form.piso_faturamento.trim() ? parseFloat(form.piso_faturamento) : null,
93	        trial_dias: form.trial_dias.trim() ? parseInt(form.trial_dias, 10) : 0,
94	        inclui_delivery: form.inclui_delivery,
95	        inclui_salao: form.inclui_salao,
96	      };
97	      if (isEdicao) {
98	        await atualizarPlano(plano.id, { ...body, ativo: form.ativo });
99	      } else {
100	        await criarPlano(body);
101	      }
102	      onSave();
103	    } catch (err) {
104	      setErro(err.message);
105	    } finally {
106	      setSalvando(false);
107	    }
108	  };
109	
110	  return (
111	    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
112	      <div className="bg-white dark:bg-zinc-800 rounded-2xl w-full max-w-md max-h-[90vh] flex flex-col">
113	        <div className="flex items-center justify-between px-6 pt-6 pb-4 flex-shrink-0">
114	          <h3 className="text-lg font-bold text-gray-900 dark:text-zinc-100">
115	            {isEdicao ? 'Editar Plano' : 'Novo Plano'}
116	          </h3>
117	          <button type="button" onClick={onClose}
118	            className="p-1.5 text-gray-400 dark:text-zinc-500 hover:text-gray-700 dark:hover:text-zinc-200 hover:bg-gray-100 dark:hover:bg-zinc-700 rounded-lg transition-colors">
